+ */
+export function ghostReapprovalRoute(
+  item: Pick<PluginMarketItem, 'installState'> | null | undefined,
+): 'market' | 'local-package' {
+  return item?.installState === 'installed' || item?.installState === 'update-available'
+    ? 'market'
